import {readFile} from 'node:fs/promises';
import vm from 'node:vm';
const root=new URL('../',import.meta.url);
const bundle=await readFile(new URL('dist/app.bundle.js',root),'utf8');
const data=JSON.parse(await readFile(new URL('dist/data/campaigns.json',root),'utf8'));
const element=()=>({innerHTML:'',addEventListener(){},querySelector(){return null;}});
const elements={app:element(),main:element()};
const document={baseURI:'https://example.test/nailo_campaign_journal/',title:'',activeElement:null,getElementById:id=>elements[id]||null,querySelector(){return null},querySelectorAll(){return[]}};
const context={console,URL,document,location:{hash:''},fetch:async()=>({ok:true,json:async()=>data}),requestAnimationFrame:callback=>callback(),setTimeout,clearTimeout,window:{addEventListener(){},scrollTo(){}}};
vm.runInNewContext(bundle,context,{filename:'app.bundle.js'});
await new Promise(resolve=>setTimeout(resolve,0));
if(!elements.app.innerHTML.includes('public-site'))throw new Error('Public app did not render.');
if(/管理後台|#\/manage/.test(elements.app.innerHTML))throw new Error('Public app contains an admin link.');
if(!elements.app.innerHTML.includes('#/hall'))throw new Error('Public app is missing the all-character hall of fame.');
const source=await readFile(new URL('dist/front.js',root),'utf8');
if(!source.includes("allCharacters(data).filter(x=>x.character.mine)"))throw new Error('Character archive is not restricted to owned characters.');
const {characters,hallOfFame,journal}=await import(new URL('dist/front.js',root));
const ownedCount=data.campaigns.flatMap(c=>c.characters).filter(character=>character.mine).length;
const allCount=data.campaigns.flatMap(c=>c.characters).length;
const playerCount=new Set(data.campaigns.flatMap(c=>c.characters).map(character=>character.player?.trim()||'未記錄玩家')).size;
const optionCount=html=>(html.match(/role="option"/g)||[]).length;
if(optionCount(characters(data))!==ownedCount)throw new Error('Character archive rendered a character that is not owned.');
const hall=hallOfFame(data);
if((hall.match(/data-hall-character=/g)||[]).length!==allCount)throw new Error('Hall of fame did not render every character.');
if((hall.match(/data-hall-player=/g)||[]).length!==playerCount)throw new Error('Hall of fame did not group characters by player.');
if(hall.includes('character-stage')||hall.includes('role="option"'))throw new Error('Hall of fame still uses the character selector layout.');
const coverData=structuredClone(data);
coverData.campaigns[0].cover='./assets/campaigns/test-cover.webp';
coverData.campaigns[0].coverAlt='測試劇本封面';
const journalHtml=journal(coverData);
if(!journalHtml.includes('class="campaign-cover"')||!journalHtml.includes('測試劇本封面'))throw new Error('Campaign journal did not render the campaign cover.');
if(journalHtml.includes('portrait-card'))throw new Error('Campaign journal still uses a character portrait as its teaser image.');
const colorData=structuredClone(data);
const owned=colorData.campaigns.flatMap(c=>c.characters.map(character=>({campaign:c,character}))).find(x=>x.character.mine);
if(!owned)throw new Error('Fixture needs at least one owned character.');
owned.character.color='#123456';
const characterHtml=characters(colorData);
if(!characterHtml.includes('--selected-character-color:#123456')||!characterHtml.includes('--portrait-bg:#123456'))throw new Error('Character archive did not apply the stored character color.');
const css=await readFile(new URL('dist/front.css',root),'utf8');
if(!css.includes('@keyframes characterPortraitInNext'))throw new Error('Character switching animation is missing.');
if(!css.includes('.campaign-cover{')||!css.includes('object-fit:cover'))throw new Error('Campaign cover is not configured as a full-bleed image.');
if(!css.includes('.story-head .status{')||!css.includes('background:#2f765a;color:#fff'))throw new Error('Story status badge contrast styles are missing.');
if(!css.includes('.portrait-feature{height:100%;min-height:620px;background:var(--portrait-bg,#375963)'))throw new Error('Character feature card does not use the stored background color.');
if(!css.includes('.selector-card>span{position:absolute;left:-4px;right:-4px;bottom:-4px'))throw new Error('Character selector label does not cover the card edge.');
console.log(`Public bundle booted with ${data.campaigns.length} campaigns and no admin link.`);
